import type { CardProps, CardHeaderProps, CardContentProps, CardDividerProps } from "./card.types";

import { Divider as DividerComponent } from "@components/divider";
import React, { forwardRef } from "react";
import { clsx } from "clsx";
import { useTheme } from "@theme";

import { CardClasses, StyledCard } from "./card.styles";

const CardRoot = forwardRef<HTMLDivElement, CardProps>(
  (
    { className, variant = "default", spacing = "default", children, ...props }: CardProps,
    ref: React.ForwardedRef<HTMLDivElement>,
  ) => {
    const theme = useTheme();
    const spacingClass = {
      default: CardClasses.spacingDefault,
      roomy: CardClasses.spacingRoomy,
      tight: CardClasses.spacingTight,
    };
    const rootClasses = clsx(CardClasses.root, spacingClass[spacing], className);

    return (
      <StyledCard
        ref={ref}
        className={rootClasses}
        currentTheme={theme}
        variant={variant}
        {...props}
      >
        {children}
      </StyledCard>
    );
  },
);

CardRoot.displayName = "Card";

const Header: React.FC<CardHeaderProps> = ({
  as: Component = "h3",
  children,
  className,
  ...props
}) => {
  return (
    <Component className={clsx(CardClasses.header, className)} {...props}>
      {children}
    </Component>
  );
};

Header.displayName = "Card.Header";

const Content: React.FC<CardContentProps> = ({ children, className, ...props }) => {
  return (
    <div className={clsx(CardClasses.content, className)} {...props}>
      {children}
    </div>
  );
};

Content.displayName = "Card.Content";

const Divider: React.FC<CardDividerProps> = ({ className, ...props }) => {
  return <DividerComponent className={clsx(CardClasses.divider, className)} {...props} />;
};

Divider.displayName = "Card.Divider";

type CardCompoundComponent = typeof CardRoot & {
  Header: typeof Header;
  Content: typeof Content;
  Divider: typeof Divider;
};

const Card = CardRoot as CardCompoundComponent;

Card.Header = Header;
Card.Content = Content;
Card.Divider = Divider;

export default Card;
